import {
  createDiagramFocus,
  type DiagramEdgeInput,
  type DiagramLabels,
  type DiagramNodeInput,
} from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { createMemo, For } from "solid-js";

import { t } from "./theme.ts" with { type: "cssints" };

export type { DiagramEdgeInput, DiagramLabels, DiagramNodeInput };

/** The graph, the words for its live region, and what a node or an edge activation goes to. */
export interface DiagramProps {
  /**
   * The nodes, in the order Home and End walk. `width` / `height` size the node and its centre; left out, the skin uses
   * its own box (120 x 44).
   */
  readonly nodes: ReadonlyArray<DiagramNodeInput>;
  /** The edges, in option order; one whose endpoints are missing is neither drawn nor offered. */
  readonly edges: ReadonlyArray<DiagramEdgeInput>;
  /** The diagram's name in the live region, and the group's accessible name; the noun for the edges (default "edges"). */
  readonly labels?: DiagramLabels | undefined;
  /** Enter or Space on the active node, and a click on it. */
  readonly onActivate?: ((nodeId: string) => void) | undefined;
  /** Enter on the edge cursor, and a click on an edge's line or label. */
  readonly onEdge?: ((edgeId: string) => void) | undefined;
  readonly class?: string | undefined;
}

/** The box a node gets when the caller gives no size: enough for a word or two. */
const NODE_WIDTH = 120;
const NODE_HEIGHT = 44;

/** A gap between a node's border and the line or the arrow's tip, so the arrow reads as pointing at the node. */
const EDGE_GAP = 4;

/** The arrow head's length along the line, and half its width. */
const ARROW = 8;
const ARROW_HALF = 3.2;

/** How far an edge's label sits above (or beside) the line. */
const LABEL_OFFSET = 8;

interface Point {
  readonly x: number;
  readonly y: number;
}

interface Route {
  /** Where the line starts and ends: both trimmed to the nodes' borders. */
  readonly from: Point;
  readonly to: Point;
  /** The arrow's three points, as `<polygon points>`. */
  readonly arrow: string;
  /** Where the label goes, and which way its text runs from there. */
  readonly label: Point & { readonly along: boolean };
}

interface RoutedEdge {
  readonly edge: DiagramEdgeInput;
  readonly route: Route;
}

const round = (value: number): number => Math.round(value * 100) / 100;

const point = (x: number, y: number): Point => ({ x: round(x), y: round(y) });

const centreOf = (node: DiagramNodeInput): Point => ({
  x: node.x + (node.width ?? NODE_WIDTH) / 2,
  y: node.y + (node.height ?? NODE_HEIGHT) / 2,
});

/**
 * How far from a node's centre its border lies along a unit direction: the first of the two axis crossings, which is what
 * an axis-aligned rectangle meets.
 */
const borderOf = (node: DiagramNodeInput, ux: number, uy: number): number => {
  const halfWidth = (node.width ?? NODE_WIDTH) / 2;
  const halfHeight = (node.height ?? NODE_HEIGHT) / 2;
  const alongX = ux === 0 ? Number.POSITIVE_INFINITY : halfWidth / Math.abs(ux);
  const alongY = uy === 0 ? Number.POSITIVE_INFINITY : halfHeight / Math.abs(uy);
  return Math.min(alongX, alongY);
};

/** The line from one node's border to the other's, the arrow at the target's end, and the label at the middle. */
const routeBetween = (from: DiagramNodeInput, to: DiagramNodeInput): Route | undefined => {
  const start = centreOf(from);
  const end = centreOf(to);
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const length = Math.hypot(dx, dy);
  if (length === 0) {
    return undefined;
  }
  const ux = dx / length;
  const uy = dy / length;
  const lineFrom = borderOf(from, ux, uy) + EDGE_GAP;
  const tip = length - borderOf(to, ux, uy) - EDGE_GAP;
  const lineTo = tip - ARROW;
  if (lineTo <= lineFrom) {
    return undefined;
  }
  const at = (distance: number): Point => point(start.x + ux * distance, start.y + uy * distance);
  const head = at(tip);
  const side = { x: -uy * ARROW_HALF, y: ux * ARROW_HALF };
  const arrow = [
    head,
    point(head.x - ux * ARROW + side.x, head.y - uy * ARROW + side.y),
    point(head.x - ux * ARROW - side.x, head.y - uy * ARROW - side.y),
  ]
    .map((corner) => `${corner.x},${corner.y}`)
    .join(" ");
  const middle = at((lineFrom + lineTo) / 2);
  // a line that runs across the page gets its label above it, one that runs down gets it beside: either way the text does
  // not sit on the line
  const along = Math.abs(ux) < Math.abs(uy);
  return {
    from: at(lineFrom),
    to: at(lineTo),
    arrow,
    label: along
      ? { x: round(middle.x + LABEL_OFFSET), y: round(middle.y + 4), along }
      : { x: middle.x, y: round(middle.y - LABEL_OFFSET), along },
  };
};

const rootClass = css.cn(css.display("grid"), css.gap(t.space._2), css.width("100%"));

// The frame is exactly the diagram's own coordinates: the SVG's viewBox and every node's left/top are in the same px, so a
// line and a node meet at the numbers the caller passed.
const frameClass = css.cn(css.position("relative"), css.flex("none"));

const edgesClass = css.cn(
  css.position("absolute"),
  css.inset("0"),
  css.display("block"),
  css.width("100%"),
  css.height("100%"),
  css.overflow("visible"),
);

// The edge group carries the colour for its line, arrow and label; the primitive's cursor is the one state that recolours
// it, read off `data-cursor` that the skin sets from `edgeCursor()`.
const edgeClass = css.cn(
  css.stroke(t.color.muted),
  css.fill(t.color.muted),
  css.strokeWidth("1.5"),
  css.strokeLinecap("round"),
  css.cursor("pointer"),
  css.attr("data-cursor", "true")(
    css.stroke(t.color.highlight),
    css.fill(t.color.highlight),
    css.strokeWidth("2"),
  ),
);

// The visible line is thin; the target is a wide transparent stroke over it, so a pointer can find an edge.
const hitClass = css.cn(
  css.stroke("transparent"),
  css.strokeWidth("14"),
  css.fill("none"),
  css.pointerEvents("stroke"),
);

const labelClass = css.cn(
  css.fontSize(t.font.sizeSm),
  css.fill(t.color.muted),
  css.textAnchor("middle"),
);

const labelAlongClass = css.cn(labelClass, css.textAnchor("start"));

// The primitive's roving tab stop is `tabindex="0"` on exactly one node: the active look needs no state of its own.
const nodeClass = css.cn(
  css.position("absolute"),
  css.display("flex"),
  css.alignItems("center"),
  css.justifyContent("center"),
  css.margin("0"),
  css.padding(t.space._2),
  css.boxSizing("border-box"),
  css.border("1px solid", t.color.border),
  css.borderRadius(t.radius.md),
  css.bg(t.color.surface),
  css.color(t.color.text),
  css.fontFamily("inherit"),
  css.fontSize(t.font.size),
  css.fontWeight("500"),
  css.textAlign("center"),
  css.lineHeight(1.25),
  css.cursor("pointer"),
  css.transition("background-color 120ms, border-color 120ms"),
  css.hover(css.bg(t.color.buttonBackground), css.borderColor(t.color.borderHover)),
  css.attr("tabindex", "0")(
    css.bg(t.color.buttonBackground),
    css.borderColor(t.color.highlight),
    css.boxShadow("inset 0 0 0 1px", t.color.highlight),
  ),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("2px")),
);

const statusClass = css.cn(css.margin("0"), css.fontSize(t.font.sizeSm), css.color(t.color.muted));

/**
 * A graph of nodes and edges, styled: `createDiagramFocus` owns one roving tab stop over the nodes (the arrows follow the
 * layout, Home / End jump, Tab leaves), the keyboard cursor over the active node's outgoing edges, and the polite live region
 * that says where the user is; the skin owns the geometry, the SVG lines behind the nodes, the tokens, the focus ring and
 * the active look it paints from `tabindex="0"`.
 *
 * A node is a button, positioned at its `x` / `y`; an edge is a line under the nodes, from border to border, with an arrow
 * head and its label, and a click on one is `onEdge` — the same activation the keyboard's edge cursor gives.
 */
export const Diagram = (props: DiagramProps): JSX.Element => {
  const nodes = createMemo(() =>
    props.nodes.map((node) => ({
      ...node,
      width: node.width ?? NODE_WIDTH,
      height: node.height ?? NODE_HEIGHT,
    })),
  );
  const diagram = createDiagramFocus({
    get nodes() {
      return nodes();
    },
    get edges() {
      return props.edges;
    },
    get labels() {
      return props.labels;
    },
    get onActivate() {
      return props.onActivate;
    },
    get onEdgeActivate() {
      return props.onEdge;
    },
  });

  // the ids the edges name, and the frame the nodes fill
  const byId = createMemo(() => new Map(nodes().map((node) => [node.id, node])));
  const bounds = createMemo(() =>
    nodes().reduce(
      (box, node) => ({
        width: Math.max(box.width, node.x + (node.width ?? NODE_WIDTH)),
        height: Math.max(box.height, node.y + (node.height ?? NODE_HEIGHT)),
      }),
      { width: 0, height: 0 },
    ),
  );
  // An edge whose endpoint is missing is the primitive's to ignore, and the skin's not to draw.
  const routed = createMemo<RoutedEdge[]>(() => {
    const found = byId();
    return props.edges.flatMap((edge) => {
      const from = found.get(edge.from);
      const to = found.get(edge.to);
      const route = from === undefined || to === undefined ? undefined : routeBetween(from, to);
      return route === undefined ? [] : [{ edge, route }];
    });
  });
  // the edge the primitive's cursor is on, for the one look the keyboard moves
  const cursor = (edgeId: string): "true" | undefined => {
    const outgoing = diagram.edgesOf(diagram.active() ?? "");
    const at = outgoing.findIndex((edge) => edge.id === edgeId);
    return at >= 0 && at === diagram.edgeCursor() ? "true" : undefined;
  };

  return (
    <div
      role="group"
      aria-label={props.labels?.diagram ?? "Diagram"}
      data-part="diagram"
      class={css.cn(rootClass, props.class)}
    >
      <div
        data-part="diagram-frame"
        class={frameClass}
        style={{ width: `${bounds().width}px`, height: `${bounds().height}px` }}
      >
        <svg
          data-part="diagram-edges"
          class={edgesClass}
          viewBox={`0 0 ${bounds().width} ${bounds().height}`}
        >
          <For each={routed()}>
            {(item) => (
              <g
                {...diagram.edgeProps(item.edge.id)}
                data-part="diagram-edge"
                data-edge={item.edge.id}
                data-cursor={cursor(item.edge.id)}
                class={edgeClass}
              >
                <line
                  class={hitClass}
                  x1={item.route.from.x}
                  y1={item.route.from.y}
                  x2={item.route.to.x}
                  y2={item.route.to.y}
                />
                <line
                  x1={item.route.from.x}
                  y1={item.route.from.y}
                  x2={item.route.to.x}
                  y2={item.route.to.y}
                />
                <polygon points={item.route.arrow} />
                {item.edge.label === undefined ? undefined : (
                  <text
                    class={item.route.label.along ? labelAlongClass : labelClass}
                    x={item.route.label.x}
                    y={item.route.label.y}
                  >
                    {item.edge.label}
                  </text>
                )}
              </g>
            )}
          </For>
        </svg>
        <For each={nodes()}>
          {(node) => (
            <button
              type="button"
              {...diagram.nodeProps(node.id)}
              data-part="diagram-node"
              data-node={node.id}
              class={nodeClass}
              style={{
                left: `${node.x}px`,
                top: `${node.y}px`,
                width: `${node.width ?? NODE_WIDTH}px`,
                height: `${node.height ?? NODE_HEIGHT}px`,
              }}
            >
              {node.label}
            </button>
          )}
        </For>
      </div>
      <p {...diagram.statusProps} data-part="diagram-status" class={statusClass}>
        {diagram.status()}
      </p>
    </div>
  );
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import { render } from "@solidjs/web";
import { createSignal } from "solid-js";

import { Diagram, type DiagramEdgeInput, type DiagramNodeInput } from "./diagram.tsx";

/** A payment flow: four steps and the five ways between them. Not a state chart — any graph reads the same. */
export const PAYMENT_NODES: ReadonlyArray<DiagramNodeInput> = [
  { id: "cart", label: "Cart", x: 0, y: 24, width: 128, height: 48 },
  { id: "paid", label: "Paid", x: 196, y: 24, width: 128, height: 48 },
  { id: "shipped", label: "Shipped", x: 392, y: 24, width: 128, height: 48 },
  { id: "refunded", label: "Refunded", x: 196, y: 172, width: 128, height: 48 },
];

export const PAYMENT_EDGES: ReadonlyArray<DiagramEdgeInput> = [
  { id: "pay", from: "cart", to: "paid", label: "pay" },
  { id: "cancel", from: "cart", to: "refunded", label: "cancel" },
  { id: "ship", from: "paid", to: "shipped", label: "ship" },
  { id: "refund", from: "paid", to: "refunded", label: "refund" },
  { id: "resend", from: "refunded", to: "shipped", label: "resend" },
];

/** The one sentence the demo shows about the keys: the primitive's, in the demo's words. */
export const DIAGRAM_HINT =
  "Keys: the arrows move along the layout, Home and End jump to the ends, e lists the edges of the active node and Enter opens one. Tab leaves the diagram.";

/** The label of a node, the way the demo's line names it. */
export const nodeLabel = (id: string): string =>
  PAYMENT_NODES.find((node) => node.id === id)?.label ?? id;

/** An edge as one sentence: its label, and the two nodes it joins. */
export const edgeLabel = (id: string): string => {
  const edge = PAYMENT_EDGES.find((candidate) => candidate.id === id);
  return edge === undefined
    ? id
    : `Edge “${edge.label ?? edge.id}”: ${nodeLabel(edge.from)} → ${nodeLabel(edge.to)}.`;
};

/** What a mounted demo hands the test: where it lives, what the host was told, and a teardown. */
export interface MountedDiagram {
  readonly root: HTMLElement;
  /** Every node activation the host heard, in order. */
  readonly activated: ReadonlyArray<string>;
  /** Every edge activation the host heard, in order. */
  readonly fired: ReadonlyArray<string>;
  /** The line under the diagram: what the host was told, in the page's words. */
  readonly log: () => string;
  readonly dispose: () => void;
}

/**
 * Mounts the styled diagram in ordinary use: the payment flow, the sentence about the keys, and the line that says what the
 * host got. A button after the diagram is where Tab lands, so the demo shows that the tab stop leaves the graph.
 */
export const mountDiagram = (): MountedDiagram => {
  const root = document.createElement("div");
  document.body.append(root);
  const activated: string[] = [];
  const fired: string[] = [];
  const [log, setLog] = createSignal("Nothing activated yet: click a node, or press Enter on it.");

  const dispose = render(
    () => (
      <div style={{ display: "grid", gap: "12px" }}>
        <Diagram
          nodes={PAYMENT_NODES}
          edges={PAYMENT_EDGES}
          labels={{ diagram: "Payment flow" }}
          onActivate={(id) => {
            activated.push(id);
            setLog(`Node “${nodeLabel(id)}” activated.`);
          }}
          onEdge={(id) => {
            fired.push(id);
            setLog(edgeLabel(id));
          }}
        />
        <p data-part="diagram-hint" style={{ margin: "0", "font-size": "12px", color: "#666" }}>
          {DIAGRAM_HINT}
        </p>
        <p data-part="diagram-log" style={{ margin: "0", "font-size": "13px" }}>
          {log()}
        </p>
        <button type="button" data-part="diagram-after">
          After the diagram
        </button>
      </div>
    ),
    root,
  );

  return {
    root,
    activated,
    fired,
    log: () => root.querySelector('[data-part="diagram-log"]')?.textContent ?? "",
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

import { userEvent } from "vite-plus/test/browser";
import { afterEach, describe, expect, it } from "vite-plus/test";

import { type MountedDiagram, mountDiagram } from "./diagram.fixture";

// No APG pattern and no Quint spec exists for a diagram, so this file is the skin's oracle: it mounts the starter in a real
// Chromium and drives the same graph a reader does. The accessible contract (a named group, one tab stop, the edges of the
// active node, the live region) is only observable through the DOM.
//
// The fixture's flow is laid out on a lattice: cart at (0, 24), paid at (196, 24), shipped at (392, 24), refunded at (196,
// 172), each node 128 x 48. Right from cart is paid, down from paid is refunded, and shipped has no outgoing edge.

/** Solid 2 delivers events through its delegated listener on a later turn. */
const settle = (): Promise<void> => new Promise((resolve) => setTimeout(resolve, 20));

const live: MountedDiagram[] = [];

const mounted = (): MountedDiagram => {
  const instance = mountDiagram();
  live.push(instance);
  return instance;
};

afterEach(() => {
  for (const instance of live.splice(0)) {
    instance.dispose();
  }
});

const required = <T extends Element>(parent: ParentNode, selector: string): T => {
  const element = parent.querySelector<T>(selector);
  if (element === null) {
    throw new Error(`diagram: no ${selector}`);
  }
  return element;
};

const node = (root: ParentNode, id: string): HTMLButtonElement =>
  required(root, `[data-part="diagram-node"][data-node="${id}"]`);

const status = (root: ParentNode): HTMLElement => required(root, '[data-part="diagram-status"]');

const tabStops = (root: ParentNode): HTMLButtonElement[] => [
  ...root.querySelectorAll<HTMLButtonElement>('[data-part="diagram-node"][tabindex="0"]'),
];

/** A key on a node, as a reader's would arrive. */
const press = async (element: HTMLElement, key: string): Promise<void> => {
  element.dispatchEvent(new KeyboardEvent("keydown", { key, bubbles: true, cancelable: true }));
  await settle();
};

describe("Diagram", () => {
  it("is a named group of node buttons with one tab stop", () => {
    const { root } = mounted();
    const group = required<HTMLElement>(root, '[data-part="diagram"]');
    const buttons = [...root.querySelectorAll<HTMLButtonElement>('[data-part="diagram-node"]')];

    expect(group.getAttribute("role")).toBe("group");
    expect(group.getAttribute("aria-label")).toBe("Payment flow");
    expect(buttons.map((button) => button.textContent)).toEqual([
      "Cart",
      "Paid",
      "Shipped",
      "Refunded",
    ]);
    expect(buttons.map((button) => button.getAttribute("aria-roledescription"))).toEqual([
      "node",
      "node",
      "node",
      "node",
    ]);
    expect(buttons.map((button) => button.getAttribute("aria-label"))).toEqual([
      "Cart",
      "Paid",
      "Shipped",
      "Refunded",
    ]);
    expect(tabStops(root).map((button) => button.dataset.node)).toEqual(["cart"]);
    expect(node(root, "paid").getAttribute("tabindex")).toBe("-1");
  });

  it("paints the active node from the primitive's tab stop", () => {
    const { root } = mounted();
    const active = node(root, "cart");
    const other = node(root, "paid");

    expect(getComputedStyle(active).borderTopColor).not.toBe(
      getComputedStyle(other).borderTopColor,
    );
    expect(getComputedStyle(active).backgroundColor).not.toBe(
      getComputedStyle(other).backgroundColor,
    );
  });

  it("moves the tab stop and the focus along the layout", async () => {
    const { root } = mounted();
    const cart = node(root, "cart");
    cart.focus();

    await press(cart, "ArrowRight");
    expect(tabStops(root).map((button) => button.dataset.node)).toEqual(["paid"]);
    expect(document.activeElement).toBe(node(root, "paid"));

    await press(node(root, "paid"), "ArrowLeft");
    expect(tabStops(root).map((button) => button.dataset.node)).toEqual(["cart"]);
    expect(document.activeElement).toBe(cart);

    await press(cart, "ArrowDown");
    expect(tabStops(root).map((button) => button.dataset.node)).toEqual(["refunded"]);
    expect(document.activeElement).toBe(node(root, "refunded"));

    await press(node(root, "refunded"), "ArrowUp");
    expect(tabStops(root).map((button) => button.dataset.node)).toEqual(["paid"]);
  });

  it("jumps to the first and last node with Home and End", async () => {
    const { root } = mounted();
    const cart = node(root, "cart");
    cart.focus();

    await press(cart, "End");
    expect(tabStops(root).map((button) => button.dataset.node)).toEqual(["refunded"]);
    expect(document.activeElement).toBe(node(root, "refunded"));

    await press(node(root, "refunded"), "Home");
    expect(tabStops(root).map((button) => button.dataset.node)).toEqual(["cart"]);
    expect(document.activeElement).toBe(cart);
  });

  it("activates the node on Enter, and the host shows what it got", async () => {
    const instance = mounted();
    const cart = node(instance.root, "cart");
    cart.focus();

    await press(cart, "Enter");
    expect(instance.activated).toEqual(["cart"]);
    expect(instance.log()).toBe("Node “Cart” activated.");

    node(instance.root, "shipped").click();
    await settle();
    expect(instance.activated).toEqual(["cart", "shipped"]);
    expect(instance.log()).toBe("Node “Shipped” activated.");
  });

  it("lists the active node's edges, moves the cursor and fires the one it is on", async () => {
    const instance = mounted();
    const { root } = instance;
    const cart = node(root, "cart");
    cart.focus();

    await press(cart, "e");
    expect(status(root).textContent).toBe(
      "Payment flow. Edge Cart → Paid (pay). Enter to activate.",
    );
    expect(required(root, '[data-edge="pay"]').getAttribute("data-cursor")).toBe("true");

    await press(cart, "ArrowDown");
    expect(status(root).textContent).toBe(
      "Payment flow. Edge Cart → Refunded (cancel). Enter to activate.",
    );
    expect(required(root, '[data-edge="cancel"]').getAttribute("data-cursor")).toBe("true");
    expect(required(root, '[data-edge="pay"]').hasAttribute("data-cursor")).toBe(false);

    await press(cart, "Enter");
    expect(instance.fired).toEqual(["cancel"]);
    expect(instance.activated).toEqual([]);
    expect(instance.log()).toBe("Edge “cancel”: Cart → Refunded.");

    // Escape leaves the cursor; the node's own announcement comes back
    await press(cart, "e");
    await press(cart, "Escape");
    expect(status(root).textContent).toBe("Payment flow. Cart. 2 edges: to Paid, to Refunded.");
  });

  it("activates an edge from a click on its line", async () => {
    const instance = mounted();
    const line = required<SVGLineElement>(instance.root, '[data-edge="pay"] line');

    line.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true }));
    await settle();

    expect(instance.fired).toEqual(["pay"]);
    expect(instance.log()).toBe("Edge “pay”: Cart → Paid.");
  });

  it("announces the active node in a polite live region", async () => {
    const { root } = mounted();
    const region = status(root);

    expect(region.getAttribute("role")).toBe("status");
    expect(region.getAttribute("aria-live")).toBe("polite");
    expect(region.textContent).toBe("Payment flow. Cart. 2 edges: to Paid, to Refunded.");

    await press(node(root, "cart"), "ArrowRight");
    expect(region.textContent).toBe("Payment flow. Paid. 2 edges: to Shipped, to Refunded.");
  });

  it("says a node has no edges, and offers none", async () => {
    const { root } = mounted();
    const shipped = node(root, "shipped");
    shipped.focus();
    await settle();

    expect(status(root).textContent).toBe("Payment flow. Shipped. No edges.");
    await press(shipped, "e");
    expect(status(root).textContent).toBe("Payment flow. Shipped. No edges.");
    expect(root.querySelector('[data-cursor="true"]')).toBeNull();
  });

  it("leaves the diagram on Tab", async () => {
    const { root } = mounted();
    const cart = node(root, "cart");
    cart.focus();

    // the primitive does not handle Tab: the page's tab order is the grid's, one stop and out
    expect(
      cart.dispatchEvent(
        new KeyboardEvent("keydown", { key: "Tab", bubbles: true, cancelable: true }),
      ),
    ).toBe(true);
    await settle();
    expect(tabStops(root).map((button) => button.dataset.node)).toEqual(["cart"]);

    await userEvent.tab();
    expect(document.activeElement).toBe(required(root, '[data-part="diagram-after"]'));
  });

  it("draws a line, an arrow and a label per edge, trimmed to the nodes' borders", () => {
    const { root } = mounted();
    const edges = [...root.querySelectorAll<SVGGElement>('[data-part="diagram-edge"]')];

    expect(edges.map((edge) => edge.dataset.edge)).toEqual([
      "pay",
      "cancel",
      "ship",
      "refund",
      "resend",
    ]);
    expect(edges.map((edge) => edge.querySelectorAll("line").length)).toEqual([2, 2, 2, 2, 2]);
    expect(edges.map((edge) => edge.querySelectorAll("polygon").length)).toEqual([1, 1, 1, 1, 1]);
    expect(edges.map((edge) => edge.querySelector("text")?.textContent)).toEqual([
      "pay",
      "cancel",
      "ship",
      "refund",
      "resend",
    ]);

    // pay runs from cart's right border (128) to paid's left border (196), arrow included, at the two centres' y
    const line = required<SVGLineElement>(root, '[data-edge="pay"] line');
    expect(Number(line.getAttribute("x1"))).toBeGreaterThan(128);
    expect(Number(line.getAttribute("x2"))).toBeLessThan(196);
    expect(line.getAttribute("y1")).toBe("48");
    expect(line.getAttribute("y2")).toBe("48");
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
